use std::sync::Arc;

use axum::Json;
use axum::extract::{Request, State};
use axum::http::{StatusCode, header};
use axum::middleware::Next;
use axum::response::{IntoResponse, Response};
use subtle::ConstantTimeEq;

/// Shared authentication state so the daemon can protect routes contributed by
/// multiple gateway modules with one bearer-token layer.
#[derive(Clone)]
pub struct AuthState {
    pub token: Arc<String>,
}

/// Every control plane endpoint requires a bearer token. The token is
/// generated by the daemon and stored with owner-only permissions.
pub async fn require_bearer(
    State(state): State<AuthState>,
    request: Request,
    next: Next,
) -> Response {
    let authorized = request
        .headers()
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "))
        .map(|candidate| {
            let expected = state.token.as_bytes();
            candidate.len() == expected.len() && candidate.as_bytes().ct_eq(expected).into()
        })
        .unwrap_or(false);

    if !authorized {
        return (
            StatusCode::UNAUTHORIZED,
            Json(serde_json::json!({ "error": "unauthorized" })),
        )
            .into_response();
    }

    next.run(request).await
}
